function urlBase64ToUint8Array(base64){let pad='='.repeat((4-base64.length%4)%4),raw=atob((base64+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(x=>x.charCodeAt(0)))}
async function consumeSSE(response,onEvent){if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||'Stream failed');if(!response.body)throw new Error('Streaming is unavailable');let reader=response.body.getReader(),decoder=new TextDecoder(),buffer='';for(;;){let{value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let parts=buffer.split('\n\n');buffer=parts.pop()||'';for(let part of parts){let event='message',lines=[];for(let line of part.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))lines.push(line.slice(5).trim())}if(lines.length)onEvent(event,JSON.parse(lines.join('\n')))}}}
